package com.zidio.keystone.exception;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,String> fields=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"message","Validation failed","fieldErrors",fields));} @ExceptionHandler(SecurityException.class) ResponseEntity<?> forbidden(SecurityException e){return ResponseEntity.status(403).body(Map.of("timestamp",Instant.now(),"status",403,"message",e.getMessage()));} @ExceptionHandler(IllegalStateException.class) ResponseEntity<?> conflict(IllegalStateException e){return ResponseEntity.status(409).body(Map.of("timestamp",Instant.now(),"status",409,"message",e.getMessage()));} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> missing(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("timestamp",Instant.now(),"status",404,"message",e.getMessage()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"message",e.getMessage()));} }
